  1→package main
  2→
  3→import (
  4→	"bufio"
  5→	"encoding/json"
  6→	"flag"
  7→	"fmt"
  8→	"io"
  9→	"os"
 10→	"regexp"
 11→	"sort"
 12→	"strings"
 13→
 14→	"golang.org/x/term"
 15→)
 16→
 17→type TestEvent struct {
 18→	Action  string  `json:"Action"`
 19→	Package string  `json:"Package"`
 20→	Test    string  `json:"Test"`
 21→	Elapsed float64 `json:"Elapsed"`
 22→	Output  string  `json:"Output"`
 23→}
 24→
 25→type subtest struct {
 26→	name    string
 27→	action  string // pass, fail, skip
 28→	elapsed float64
 29→	output  []string
 30→}
 31→
 32→type parentTest struct {
 33→	name     string
 34→	action   string
 35→	elapsed  float64
 36→	children []*subtest
 37→}
 38→
 39→func main() {
 40→	colorFlag := flag.Bool("color", false, "Force color output (default: auto-detect TTY)")
 41→	outputFile := flag.String("o", "", "Write output to file (ANSI + .nocolor.txt)")
 42→	flag.Parse()
 43→
 44→	useColor := *colorFlag || term.IsTerminal(int(os.Stdout.Fd()))
 45→
 46→	r, err := openInput(flag.Arg(0))
 47→	if err != nil {
 48→		fmt.Fprintf(os.Stderr, "error: %v\n", err)
 49→		os.Exit(1)
 50→	}
 51→
 52→	parents := parseEvents(r)
 53→	report := renderReport(parents, useColor)
 54→
 55→	fmt.Print(report)
 56→
 57→	if *outputFile != "" {
 58→		colorReport := renderReport(parents, true)
 59→		if err := os.WriteFile(*outputFile, []byte(colorReport), 0644); err != nil {
 60→			fmt.Fprintf(os.Stderr, "error writing %s: %v\n", *outputFile, err)
 61→			os.Exit(1)
 62→		}
 63→		noColorFile := strings.TrimSuffix(*outputFile, ".txt") + ".nocolor.txt"
 64→		plainReport := stripANSI(colorReport)
 65→		if err := os.WriteFile(noColorFile, []byte(plainReport), 0644); err != nil {
 66→			fmt.Fprintf(os.Stderr, "error writing %s: %v\n", noColorFile, err)
 67→			os.Exit(1)
 68→		}
 69→	}
 70→}
 71→
 72→func openInput(path string) (io.Reader, error) {
 73→	if path == "" {
 74→		return os.Stdin, nil
 75→	}
 76→	return os.Open(path)
 77→}
 78→
 79→func parseEvents(r io.Reader) []*parentTest {
 80→	scanner := bufio.NewScanner(r)
 81→	scanner.Buffer(make([]byte, 0, 1024*1024), 1024*1024)
 82→
 83→	type testInfo struct {
 84→		action  string
 85→		elapsed float64
 86→		output  []string
 87→	}
 88→
 89→	tests := make(map[string]*testInfo)
 90→
 91→	for scanner.Scan() {
 92→		var ev TestEvent
 93→		if err := json.Unmarshal(scanner.Bytes(), &ev); err != nil {
 94→			continue
 95→		}
 96→		if ev.Test == "" {
 97→			continue
 98→		}
 99→
100→		info, ok := tests[ev.Test]
101→		if !ok {
102→			info = &testInfo{}
103→			tests[ev.Test] = info
104→		}
105→
106→		switch ev.Action {
107→		case "pass", "fail", "skip":
108→			info.action = ev.Action
109→			info.elapsed = ev.Elapsed
110→		case "output":
111→			info.output = append(info.output, ev.Output)
112→		}
113→	}
114→
115→	// Group by parent
116→	parentMap := make(map[string]*parentTest)
117→	for name, info := range tests {
118→		parentName, childName := splitTestName(name)
119→		if childName == "" {
120→			// This is a parent test (or standalone)
121→			p, ok := parentMap[parentName]
122→			if !ok {
123→				p = &parentTest{name: parentName}
124→				parentMap[parentName] = p
125→			}
126→			p.action = info.action
127→			p.elapsed = info.elapsed
128→			continue
129→		}
130→
131→		p, ok := parentMap[parentName]
132→		if !ok {
133→			p = &parentTest{name: parentName}
134→			parentMap[parentName] = p
135→		}
136→		p.children = append(p.children, &subtest{
137→			name:    childName,
138→			action:  info.action,
139→			elapsed: info.elapsed,
140→			output:  info.output,
141→		})
142→	}
143→
144→	// Sort parents alphabetically, children alphabetically
145→	var result []*parentTest
146→	for _, p := range parentMap {
147→		sort.Slice(p.children, func(i, j int) bool {
148→			return p.children[i].name < p.children[j].name
149→		})
150→		result = append(result, p)
151→	}
152→	sort.Slice(result, func(i, j int) bool {
153→		return result[i].name < result[j].name
154→	})
155→
156→	return result
157→}
158→
159→func splitTestName(name string) (parent, child string) {
160→	parent, child, ok := strings.Cut(name, "/")
161→	if !ok {
162→		return name, ""
163→	}
164→	return parent, child
165→}
166→
167→func renderReport(parents []*parentTest, color bool) string {
168→	var b strings.Builder
169→
170→	// Count totals
171→	var total, passed, failed, skipped int
172→	for _, p := range parents {
173→		total++
174→		switch p.action {
175→		case "pass":
176→			passed++
177→		case "fail":
178→			failed++
179→		case "skip":
180→			skipped++
181→		}
182→	}
183→
184→	// Header
185→	b.WriteString("E2E Test Report\n")
186→	b.WriteString("═══════════════\n\n")
187→	fmt.Fprintf(&b, "Total: %d  Passed: %d  Failed: %d  Skipped: %d\n\n", total, passed, failed, skipped)
188→
189→	for _, p := range parents {
190→		icon := statusIcon(p.action, color)
191→		if p.elapsed > 0 {
192→			fmt.Fprintf(&b, "%s %s (%.1fs)\n", icon, p.name, p.elapsed)
193→		} else {
194→			fmt.Fprintf(&b, "%s %s\n", icon, p.name)
195→		}
196→
197→		for _, c := range p.children {
198→			cIcon := statusIcon(c.action, color)
199→			switch c.action {
200→			case "skip":
201→				reason := extractSkipReason(c.output)
202→				fmt.Fprintf(&b, "  %s %-20s SKIP", cIcon, c.name)
203→				if reason != "" {
204→					fmt.Fprintf(&b, ": %s", reason)
205→				}
206→				b.WriteString("\n")
207→			case "fail":
208→				fmt.Fprintf(&b, "  %s %-20s %.1fs\n", cIcon, c.name, c.elapsed)
209→				for _, line := range filterFailureOutput(c.output) {
210→					fmt.Fprintf(&b, "      %s\n", line)
211→				}
212→			default:
213→				fmt.Fprintf(&b, "  %s %-20s %.1fs\n", cIcon, c.name, c.elapsed)
214→			}
215→		}
216→
217→		b.WriteString("\n")
218→	}
219→
220→	// Footer banner
221→	if failed > 0 {
222→		banner := fmt.Sprintf("💥 FAILED (%d/%d passed) 💥", passed, total)
223→		if color {
224→			fmt.Fprintf(&b, "%s%s%s\n", colorRed, banner, colorReset)
225→		} else {
226→			b.WriteString(banner + "\n")
227→		}
228→	} else {
229→		banner := fmt.Sprintf("🎉 ALL %d TESTS PASSED 🎉", total)
230→		if color {
231→			fmt.Fprintf(&b, "%s%s%s\n", colorGreen, banner, colorReset)
232→		} else {
233→			b.WriteString(banner + "\n")
234→		}
235→	}
236→	b.WriteString("\n")
237→
238→	return b.String()
239→}
240→
241→const (
242→	colorGreen  = "\033[32m"
243→	colorRed    = "\033[31m"
244→	colorYellow = "\033[33m"
245→	colorReset  = "\033[0m"
246→)
247→
248→func statusIcon(action string, color bool) string {
249→	switch action {
250→	case "pass":
251→		if color {
252→			return colorGreen + "✓" + colorReset
253→		}
254→		return "✓"
255→	case "fail":
256→		if color {
257→			return colorRed + "✗" + colorReset
258→		}
259→		return "✗"
260→	case "skip":
261→		if color {
262→			return colorYellow + "−" + colorReset
263→		}
264→		return "−"
265→	default:
266→		return "?"
267→	}
268→}
269→
270→func extractSkipReason(output []string) string {
271→	for _, line := range output {
272→		trimmed := strings.TrimSpace(line)
273→		if strings.HasPrefix(trimmed, "--- SKIP") || strings.HasPrefix(trimmed, "=== RUN") {
274→			continue
275→		}
276→		if trimmed == "" {
277→			continue
278→		}
279→		return trimmed
280→	}
281→	return ""
282→}
283→
284→func filterFailureOutput(output []string) []string {
285→	var lines []string
286→	for _, line := range output {
287→		trimmed := strings.TrimSpace(line)
288→		if trimmed == "" {
289→			continue
290→		}
291→		if strings.HasPrefix(trimmed, "=== RUN") ||
292→			strings.HasPrefix(trimmed, "=== PAUSE") ||
293→			strings.HasPrefix(trimmed, "=== CONT") ||
294→			strings.HasPrefix(trimmed, "--- FAIL") ||
295→			strings.HasPrefix(trimmed, "--- PASS") {
296→			continue
297→		}
298→		lines = append(lines, trimmed)
299→	}
300→	return lines
301→}
302→
303→var ansiRegexp = regexp.MustCompile(`\x1b\[[0-9;]*m`)
304→
305→func stripANSI(s string) string {
306→	return ansiRegexp.ReplaceAllString(s, "")
307→}
